BEGIN;
-- SHARED_OWNER_COMPONENT_FIXTURE
CREATE FUNCTION pg_temp.content_call(p_operation text,p_args jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE actor uuid;admission uuid;r jsonb;
BEGIN
 SELECT auth_user_id INTO actor FROM public.sandy_controller_admins WHERE role='owner' AND enabled ORDER BY created_at LIMIT 1;
 admission:=pg_temp.sandy_owner_component_admission(p_operation,p_args,'f03c397e8c2ba3276d669cab643832a891899f6529274da2de1d6b52fd99c1ad');
 r:=public.sandy_tenant_content_execute(actor,admission,p_args::text);
 IF r->>'ok'<>'true' OR public.sandy_tenant_content_execute(actor,admission,p_args::text) IS DISTINCT FROM (r||jsonb_build_object('reused',true)) THEN RAISE EXCEPTION 'content_transactional_receipt_failed';END IF;
 RETURN r->'result';
END $$;
DO $test$
DECLARE tenant uuid:=gen_random_uuid();subject uuid:=gen_random_uuid();foreign_tenant uuid:=gen_random_uuid();foreign_subject uuid:=gen_random_uuid();email text:='content-fixture-'||gen_random_uuid()::text||'@example.invalid';document uuid:=gen_random_uuid();manifest jsonb:=public.sandy_tenant_content_manifest_v1();args jsonb;r jsonb;fragment jsonb;record_data record;snapshot uuid;stream text:='';chunks integer:=0;refused boolean;first_vault uuid;original_material text;job_count integer;support_case uuid:=gen_random_uuid();comment uuid:=gen_random_uuid();draft uuid:=gen_random_uuid();foreign_case uuid:=gen_random_uuid();original_definition text;document_chain text;expected_chain text;snapshot_count integer;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.sandy_operation_registry WHERE operation='supabase.tenant.content.exports.download' AND error_contract->>'artifact_digest_encoding'='sha256_of_decoded_artifact_json_utf8' AND output_schema->'properties' ? 'artifact_json') THEN RAISE EXCEPTION 'content_canonical_artifact_envelope_contract_missing';END IF;
 IF has_table_privilege('authenticated','public.sandy_tenant_content_fragments','SELECT') OR has_table_privilege('service_role','public.sandy_tenant_content_snapshots','UPDATE') OR has_function_privilege('service_role','public.sandy_tenant_content_fragment_download(uuid,integer)','EXECUTE') OR has_function_privilege('authenticated','public.sandy_tenant_content_execute(uuid,uuid,text)','EXECUTE') OR has_function_privilege('service_role','public.sandy_tenant_content_capture_v1(uuid)','EXECUTE') THEN RAISE EXCEPTION 'content_private_boundary_acl_invalid';END IF;
 INSERT INTO auth.users(id,email,email_confirmed_at,created_at,updated_at,raw_app_meta_data,raw_user_meta_data) VALUES(subject,email,clock_timestamp(),clock_timestamp(),clock_timestamp(),'{}','{}'),(foreign_subject,'foreign-'||email,clock_timestamp(),clock_timestamp(),clock_timestamp(),'{}','{}');
 INSERT INTO public.email_customers(id,display_name) VALUES(tenant,'SYNTHETIC CONTENT CUSTOMER'),(foreign_tenant,'SYNTHETIC FOREIGN');
 INSERT INTO public.email_customer_addresses(customer_id,email_address,is_primary) VALUES(tenant,email,true),(foreign_tenant,'foreign-'||email,true);
 INSERT INTO public.sandy_memory_portal_accounts(auth_user_id,customer_id) VALUES(subject,tenant),(foreign_subject,foreign_tenant);
 -- Native uncommitted indexing job is never visible to an external worker.
 -- No trigger is disabled and no parent is ever restored by this adapter.
 INSERT INTO public.sandy_knowledge_documents(id,owner_customer_id,source_kind,external_id,title,status,extracted_text,metadata,source_ref) VALUES(document,tenant,'upload','SYNTHETIC EXTERNAL HANDLE','SYNTHETIC LARGE CONTENT','ready',repeat('🍋',800000),'{"refresh_token":"fixture-do-not-export"}','{"provider":"fixture-source-ref"}');
 SELECT count(*) INTO job_count FROM public.sandy_knowledge_jobs WHERE document_id=document;
 IF job_count<>1 THEN RAISE EXCEPTION 'content_native_parent_fixture_review_changed';END IF;
 INSERT INTO public.sandy_product_support_cases(id,customer_id,subject,details,category) VALUES(support_case,tenant,'SYNTHETIC CASE','SYNTHETIC CASE BODY','privacy'),(foreign_case,foreign_tenant,'SYNTHETIC FOREIGN CASE','FOREIGN BODY MUST NOT EXPORT','other');
 INSERT INTO public.sandy_product_support_comments(id,case_id,actor_id,body) VALUES(comment,support_case,subject,'SYNTHETIC PRIVATE COMMENT'),(gen_random_uuid(),foreign_case,foreign_subject,'FOREIGN COMMENT MUST NOT EXPORT');
 INSERT INTO public.sandy_product_notification_preferences(customer_id,email_enabled,whatsapp_enabled) VALUES(tenant,true,true);
 INSERT INTO public.sandy_product_notification_quiet_hours(customer_id,enabled,timezone,start_minute,end_minute) VALUES(tenant,true,'UTC',1320,420);
 INSERT INTO public.sandy_product_notification_subscriptions(customer_id,topic,enabled) VALUES(tenant,'support',false);
 INSERT INTO public.sandy_product_notification_inbox(customer_id,topic,event,resource_id) VALUES(tenant,'support','case_created',support_case);
 INSERT INTO public.sandy_product_whatsapp_media(customer_id,provider_id,filename,content_type) VALUES(tenant,'SYNTHETIC PROVIDER MEDIA HANDLE','fixture.txt','text/plain');
 INSERT INTO public.sandy_product_graph_drafts(id,customer_id,provider_id,recipient,recipients,state) VALUES(draft,tenant,'SYNTHETIC PROVIDER DRAFT HANDLE','fixture@example.invalid','["fixture@example.invalid"]','draft'),(gen_random_uuid(),foreign_tenant,'FOREIGN PROVIDER HANDLE','foreign@example.invalid','{"token":"foreign fixture secret"}','unknown');
 UPDATE public.sandy_operation_registry SET api_exposed=true,verified=true WHERE handler='sandy-tenant-lifecycle-api' OR operation IN('supabase.tenant.consent.set','supabase.tenant.content.exports.download','supabase.tenant.content.exports.available');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',subject,'role','authenticated')::text,true);
 PERFORM public.sandy_supabase_tenant_consent_set(ARRAY(SELECT operation FROM public.sandy_operation_registry WHERE handler='sandy-tenant-lifecycle-api'),ARRAY[]::text[],true,clock_timestamp()+interval '1 hour');
 args:=jsonb_build_object('tenant_id',tenant,'manifest',manifest->>'id','expected_manifest_sha256',manifest->>'manifest_sha256');
 r:=pg_temp.content_call('supabase.tenant.content.export',args);snapshot:=(r->>'snapshot_id')::uuid;
 IF (r->>'total_plaintext_bytes')::bigint<=2097152 OR (r->>'fragment_count')::integer<=12 OR r->>'complete_tenant_coverage'<>'false' OR r->>'erasure_supported'<>'false' OR r->>'restore_supported'<>'false' OR r::text LIKE '%json_fragment%' OR r::text LIKE '%vault%' OR r::text LIKE '%SYNTHETIC LARGE%' THEN RAISE EXCEPTION 'content_large_export_metadata_projection_failed';END IF;
 r:=public.sandy_tenant_content_exports_available(0,1);
 IF r->>'ok'<>'true' OR r->>'total_count'<>'1' OR r->'items'->0->>'snapshot_id'<>snapshot::text OR r->>'next_offset' IS NOT NULL OR r::text LIKE '%vault_secret%' THEN RAISE EXCEPTION 'content_customer_discovery_invalid';END IF;
 FOR record_data IN SELECT sequence,artifact_sha256 FROM public.sandy_tenant_content_fragments WHERE snapshot_id=snapshot ORDER BY sequence LOOP
  r:=public.sandy_tenant_content_fragment_download(snapshot,record_data.sequence);
  IF r->>'ok'<>'true' OR encode(extensions.digest(r->>'artifact_json','sha256'),'hex') IS DISTINCT FROM r->>'artifact_sha256' THEN RAISE EXCEPTION 'content_customer_fragment_digest_failed';END IF;
  fragment:=(r->>'artifact_json')::jsonb;
  IF char_length(fragment->>'json_fragment')>65536 OR fragment->>'snapshot_id'<>snapshot::text OR (fragment->>'sequence')::integer<>chunks THEN RAISE EXCEPTION 'content_fragment_binding_or_bound_failed';END IF;
  IF fragment->>'table'='sandy_product_support_comments' AND (fragment->>'json_fragment' LIKE '%actor_id%' OR fragment->>'json_fragment' LIKE '%FOREIGN COMMENT%' OR fragment->>'json_fragment' NOT LIKE '%SYNTHETIC PRIVATE COMMENT%') THEN RAISE EXCEPTION 'content_indirect_comment_owner_or_actor_projection_failed';END IF;
  IF fragment->>'table' IN('sandy_product_graph_drafts','sandy_product_whatsapp_media') AND (fragment->>'json_fragment' LIKE '%provider_id%' OR fragment->>'json_fragment' LIKE '%SYNTHETIC PROVIDER%') THEN RAISE EXCEPTION 'content_product_provider_handle_leaked';END IF;
  IF fragment->>'table'='sandy_knowledge_documents' THEN stream:=stream||(fragment->>'json_fragment');IF (fragment->>'table_complete')::boolean THEN document_chain:=fragment->>'table_row_chain_sha256';END IF;END IF;
  chunks:=chunks+1;
 END LOOP;
 IF (stream::jsonb)->>'extracted_text' IS DISTINCT FROM repeat('🍋',800000) OR stream LIKE '%fixture-do-not-export%' OR stream LIKE '%SYNTHETIC EXTERNAL HANDLE%' OR (stream::jsonb) ? 'metadata' OR (stream::jsonb) ? 'source_ref' OR (stream::jsonb) ? 'storage_path' OR (stream::jsonb) ? 'external_id' THEN RAISE EXCEPTION 'content_unicode_reassembly_or_secret_exclusion_failed';END IF;
 expected_chain:=encode(extensions.digest(manifest->>'manifest_sha256'||':sandy_knowledge_documents','sha256'),'hex');
 expected_chain:=encode(extensions.digest(expected_chain||E'\n'||stream,'sha256'),'hex');
 IF document_chain IS DISTINCT FROM expected_chain THEN RAISE EXCEPTION 'content_row_chain_reassembly_invalid';END IF;
 SELECT count(*) INTO snapshot_count FROM public.sandy_tenant_content_snapshots WHERE tenant_id=tenant;
 UPDATE public.sandy_knowledge_documents SET extracted_text=repeat('x',17000000) WHERE id=document;
 refused:=false;BEGIN PERFORM pg_temp.content_call('supabase.tenant.content.export',args);EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'tenant_content_row_byte_bound_exceeded' THEN RAISE;END IF;refused:=true;END;
 IF NOT refused OR (SELECT count(*) FROM public.sandy_tenant_content_snapshots WHERE tenant_id=tenant)<>snapshot_count THEN RAISE EXCEPTION 'content_oversized_row_created_partial_snapshot';END IF;
 UPDATE public.sandy_knowledge_documents SET extracted_text=repeat('🍋',800000) WHERE id=document;
 UPDATE public.sandy_product_graph_drafts SET recipients='{"token":"fixture-do-not-export"}'::jsonb WHERE id=draft;
 refused:=false;BEGIN PERFORM pg_temp.content_call('supabase.tenant.content.export',args);EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'tenant_content_draft_recipients_projection_refused' THEN RAISE;END IF;refused:=true;END;
 IF NOT refused THEN RAISE EXCEPTION 'content_arbitrary_draft_JSON_exported';END IF;
 UPDATE public.sandy_product_graph_drafts SET recipients='["fixture@example.invalid"]'::jsonb WHERE id=draft;
 SELECT pg_get_functiondef('public.sandy_tenant_content_manifest_v1()'::regprocedure) INTO original_definition;
 EXECUTE replace(original_definition,manifest->>'schema_sha256',repeat('0',64));
 refused:=false;BEGIN PERFORM pg_temp.content_call('supabase.tenant.content.export',args);EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'tenant_content_schema_changed' THEN RAISE;END IF;refused:=true;END;
 EXECUTE original_definition;
 IF NOT refused THEN RAISE EXCEPTION 'content_projection_schema_drift_accepted';END IF;
 IF (SELECT count(*) FROM public.sandy_knowledge_jobs WHERE document_id=document)<>job_count OR (SELECT revision FROM public.sandy_knowledge_documents WHERE id=document)<>1 THEN RAISE EXCEPTION 'content_export_replayed_parent_work';END IF;
 PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
 IF public.sandy_tenant_content_exports_available(0,1)->>'http_status'<>'403' OR public.sandy_tenant_content_fragment_download(snapshot,0)->>'http_status'<>'403' THEN RAISE EXCEPTION 'content_admin_substituted_for_customer';END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',foreign_subject,'role','authenticated')::text,true);
 IF public.sandy_tenant_content_exports_available(0,1)->>'total_count'<>'0' OR public.sandy_tenant_content_fragment_download(snapshot,0)->>'http_status'<>'404' THEN RAISE EXCEPTION 'content_cross_customer_download_allowed';END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',subject,'role','authenticated')::text,true);
 IF public.sandy_tenant_content_fragment_download(snapshot,-1)->>'http_status'<>'404' OR public.sandy_tenant_content_fragment_download(snapshot,2048)->>'http_status'<>'404' THEN RAISE EXCEPTION 'content_invalid_sequence_allowed';END IF;
 SELECT vault_secret_id INTO first_vault FROM public.sandy_tenant_content_fragments WHERE snapshot_id=snapshot AND sequence=0;
 SELECT decrypted_secret INTO original_material FROM vault.decrypted_secrets WHERE id=first_vault;
 PERFORM vault.update_secret(first_vault,'{"tampered":true}');
 refused:=false;BEGIN PERFORM public.sandy_tenant_content_fragment_download(snapshot,0);EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'tenant_content_fragment_integrity_failed' THEN RAISE;END IF;refused:=true;END;
 IF NOT refused THEN RAISE EXCEPTION 'content_tampered_artifact_delivered';END IF;
 PERFORM vault.update_secret(first_vault,original_material);
 UPDATE public.sandy_supabase_tenant_consents SET allow_erasure=false WHERE tenant_id=tenant;
 refused:=false;BEGIN PERFORM pg_temp.content_call('supabase.tenant.content.exports.purge',jsonb_build_object('tenant_id',tenant,'snapshot_id',snapshot,'confirm_artifact_purge',true));EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'tenant_lifecycle_hold_or_retention_refused' THEN RAISE;END IF;refused:=true;END;
 IF NOT refused OR NOT EXISTS(SELECT 1 FROM vault.secrets WHERE id=first_vault) THEN RAISE EXCEPTION 'content_purged_without_erasure_consent';END IF;
 UPDATE public.sandy_supabase_tenant_consents SET allow_erasure=true WHERE tenant_id=tenant;
 UPDATE public.sandy_supabase_tenant_controls SET legal_hold=true WHERE tenant_id=tenant;
 refused:=false;BEGIN PERFORM pg_temp.content_call('supabase.tenant.content.exports.purge',jsonb_build_object('tenant_id',tenant,'snapshot_id',snapshot,'confirm_artifact_purge',true));EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'tenant_lifecycle_hold_or_retention_refused' THEN RAISE;END IF;refused:=true;END;
 IF NOT refused OR NOT EXISTS(SELECT 1 FROM vault.secrets WHERE id=first_vault) THEN RAISE EXCEPTION 'content_held_payload_purged';END IF;
 UPDATE public.sandy_supabase_tenant_controls SET legal_hold=false,retention_until=clock_timestamp()+interval '1 day' WHERE tenant_id=tenant;
 refused:=false;BEGIN PERFORM pg_temp.content_call('supabase.tenant.content.exports.purge',jsonb_build_object('tenant_id',tenant,'snapshot_id',snapshot,'confirm_artifact_purge',true));EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'tenant_lifecycle_hold_or_retention_refused' THEN RAISE;END IF;refused:=true;END;
 IF NOT refused THEN RAISE EXCEPTION 'content_retained_payload_purged';END IF;
 UPDATE public.sandy_supabase_tenant_controls SET retention_until=NULL WHERE tenant_id=tenant;
 UPDATE public.sandy_tenant_content_snapshots SET expires_at=clock_timestamp()-interval '1 second' WHERE id=snapshot;
 IF public.sandy_tenant_content_fragment_download(snapshot,0)->>'http_status'<>'410' THEN RAISE EXCEPTION 'content_expired_fragment_delivered';END IF;
 r:=pg_temp.content_call('supabase.tenant.content.exports.get',jsonb_build_object('tenant_id',tenant,'snapshot_id',snapshot));
 IF r->>'fragment_count'<>chunks::text THEN RAISE EXCEPTION 'content_private_metadata_readback_failed';END IF;
 r:=pg_temp.content_call('supabase.tenant.content.exports.purge',jsonb_build_object('tenant_id',tenant,'snapshot_id',snapshot,'confirm_artifact_purge',true));
 IF r->>'state'<>'purged' OR EXISTS(SELECT 1 FROM public.sandy_tenant_content_fragments WHERE snapshot_id=snapshot AND vault_secret_id IS NOT NULL) OR EXISTS(SELECT 1 FROM vault.secrets WHERE name LIKE 'sandy_tenant_content_v1_'||snapshot::text||'_%') OR NOT EXISTS(SELECT 1 FROM public.sandy_knowledge_documents WHERE id=document) THEN RAISE EXCEPTION 'content_purge_readback_or_parent_preservation_failed';END IF;
 IF public.sandy_tenant_content_fragment_download(snapshot,0)->>'http_status'<>'410' THEN RAISE EXCEPTION 'content_purged_fragment_delivered';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.sandy_product_notification_preferences WHERE customer_id=tenant AND email_enabled AND whatsapp_enabled) OR NOT EXISTS(SELECT 1 FROM public.sandy_product_notification_quiet_hours WHERE customer_id=tenant AND enabled) OR NOT EXISTS(SELECT 1 FROM public.sandy_product_notification_subscriptions WHERE customer_id=tenant AND topic='support' AND NOT enabled) THEN RAISE EXCEPTION 'content_export_mutated_communication_permissions';END IF;
END $test$;
SELECT jsonb_build_object('passed',true,'layer','administrative_database_component','fixtures','full_rollback','typed_projection_tables',20,'large_unicode_source_bytes',3200000,'whole_tenant_coverage',false,'parent_erasure_or_restore',false,'real_auth_session_tested',false,'real_owner_approval_tested',false,'provider_called',false,'checks',jsonb_build_array('private_table_and_function_acl','real_encrypted_multi_fragment_export','payload_above_two_MiB','bounded_unicode_fragments','exact_digest_each_fragment','metadata_only_owner_results','actual_claim_only_customer_delivery','cross_customer_refusal','service_key_not_customer_session','exact_snapshot_sequence_binding','unicode_NDJSON_reassembly','operational_JSON_external_handle_exclusion','no_parent_revision_or_worker_replay','tampered_payload_refusal','legal_hold_refusal','retention_refusal','expired_fragment_refusal','private_metadata_readback','all_encrypted_fragments_purge','parent_customer_content_preserved','purged_delivery_refusal','shared_transactional_receipt_reuse','customer_own_export_discovery','cross_customer_discovery_refusal','reassembled_row_chain_digest','row_byte_bound_without_partial_snapshot','projection_schema_drift_refusal','eight_product_projections_populated','indirect_case_customer_ownership','staff_Auth_actor_UUID_excluded','Graph_Meta_provider_handles_excluded','notification_policy_read_only','erasure_consent_required_for_artifact_purge','draft_JSON_email_array_only','foreign_invalid_draft_JSON_cannot_interfere','canonical_decoded_artifact_digest_contract')) AS evidence;
ROLLBACK;
